import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore

private const val WAITLISTS_COLLECTION = "waitlists"

/**
 * Documentation generated by Gemini
 * Displays detailed information and action controls for a specific campsite.
 *
 * @param navController Navigation controller for routing back or navigating to edit forms.
 * @param campsiteId Firestore document ID of the campsite to display.
 */
@Composable
fun CampsiteInfoScreen(
    navController: NavController,
    campsiteId: String,
) {
    val context = LocalContext.current
    val currentDeviceId = remember(context) { DeviceIdentity.getDeviceId(context) }

    var campsite by remember { mutableStateOf<Campsite?>(null) }
    var currentUser by remember { mutableStateOf<User?>(null) }
    var isLoading by remember { mutableStateOf(true) }

    var openWaitlists by remember { mutableStateOf<List<Waitlist>>(emptyList()) }
    var joinMessage by remember { mutableStateOf<String?>(null) }
    var joinError by remember { mutableStateOf<String?>(null) }
    var isJoining by remember { mutableStateOf(false) }

    LaunchedEffect(campsiteId) {
        val db = FirebaseFirestore.getInstance()
        db.collection("campsites").document(campsiteId).get()
            .addOnSuccessListener { doc ->
                campsite = doc.toObject(Campsite::class.java)
                db.collection("users").document(currentDeviceId).get()
                    .addOnSuccessListener { userDoc ->
                        currentUser = userDoc.toObject(User::class.java)
                        isLoading = false
                    }
                    .addOnFailureListener { isLoading = false }
            }
            .addOnFailureListener { isLoading = false }
    }

    // Live waitlists that include this campsite (US 01.02.01 join target).
    DisposableEffect(campsiteId) {
        val listener = FirebaseFirestore.getInstance()
            .collection(WAITLISTS_COLLECTION)
            .whereArrayContains("campsiteIds", campsiteId)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    joinError = error.message
                    return@addSnapshotListener
                }
                openWaitlists = snapshot?.documents?.mapNotNull { doc ->
                    runCatching { doc.toObject(Waitlist::class.java) }.getOrNull()
                }.orEmpty()
            }
        onDispose { listener.remove() }
    }

    val joinable = openWaitlists.filter { it.isRegistrationOpen() && !it.isFull() }
    val alreadyJoined = openWaitlists.any { currentDeviceId in it.joinedEntrantIds }
    val activeJoined = openWaitlists.firstOrNull { currentDeviceId in it.joinedEntrantIds }

    fun joinWaitlist() {
        if (isJoining) return
        joinError = null
        joinMessage = null
        val target = joinable.firstOrNull { currentDeviceId !in it.joinedEntrantIds }
        if (target == null) {
            joinError = when {
                alreadyJoined -> "You are already on this campsite's waitlist."
                openWaitlists.isEmpty() -> "No lottery is listed for this campsite yet."
                else -> "No open lottery with space to join right now."
            }
            return
        }
        isJoining = true
        FirebaseFirestore.getInstance()
            .collection(WAITLISTS_COLLECTION)
            .document(target.waitlistId)
            .update("joinedEntrantIds", FieldValue.arrayUnion(currentDeviceId))
            .addOnSuccessListener {
                isJoining = false
                joinMessage = "Joined the lottery waitlist."
            }
            .addOnFailureListener {
                isJoining = false
                joinError = it.message ?: "Could not join waitlist"
            }
    }

    fun leaveWaitlist() {
        val target = activeJoined ?: return
        if (isJoining) return
        isJoining = true
        joinError = null
        joinMessage = null
        FirebaseFirestore.getInstance()
            .collection(WAITLISTS_COLLECTION)
            .document(target.waitlistId)
            .update("joinedEntrantIds", FieldValue.arrayRemove(currentDeviceId))
            .addOnSuccessListener {
                isJoining = false
                joinMessage = "Left the lottery waitlist."
            }
            .addOnFailureListener {
                isJoining = false
                joinError = it.message ?: "Could not leave waitlist"
            }
    }

    val isOwnerOfSite = campsite != null && campsite!!.ownerId == currentDeviceId
    val isAdmin = currentUser?.isAdmin == true
    val canEdit = isOwnerOfSite
    val canDelete = isOwnerOfSite || isAdmin

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.Absolute.Left,
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                modifier = Modifier.testTag("toBackButton"),
            ) {
                Text("Back")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
            }
            campsite == null -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("Campsite details not found.", fontSize = 20.sp)
                }
            }
            else -> {
                Text(text = campsite!!.name, fontSize = 40.sp)
                Spacer(modifier = Modifier.height(8.dp))
                Text(text = "Location: ${campsite!!.address}", fontSize = 18.sp)
                Text(
                    text = "Max Occupancy: ${campsite!!.maxOccupancy} | Price: $${campsite!!.pricePerNight}/night",
                    fontSize = 16.sp,
                )
                Spacer(modifier = Modifier.height(16.dp))
                Text(text = campsite!!.description, fontSize = 18.sp)
                if (campsite!!.rules.isNotBlank()) {
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(text = "Rules: ${campsite!!.rules}", fontSize = 14.sp)
                }
            }
        }

        Spacer(modifier = Modifier.weight(1f))

        Column(modifier = Modifier.fillMaxWidth()) {
            joinError?.let {
                Text(it, color = MaterialTheme.colorScheme.error, fontSize = 14.sp)
                Spacer(modifier = Modifier.height(4.dp))
            }
            joinMessage?.let {
                Text(it, fontSize = 14.sp)
                Spacer(modifier = Modifier.height(4.dp))
            }

            if (canEdit) {
                Button(
                    onClick = { navController.navigate("registerCampsite/$campsiteId") },
                    shape = RectangleShape,
                    modifier = Modifier.fillMaxWidth(),
                ) {
                    Text("Edit Campsite Details")
                }
                Spacer(modifier = Modifier.height(8.dp))
            }

            if (canDelete) {
                Button(
                    onClick = {
                        FirebaseFirestore.getInstance()
                            .collection("campsites")
                            .document(campsiteId)
                            .delete()
                            .addOnSuccessListener { navController.popBackStack() }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                    shape = RectangleShape,
                    modifier = Modifier.fillMaxWidth().testTag("deleteCampsiteButton"),
                ) {
                    Text("Delete Campsite", color = Color.White)
                }
                Spacer(modifier = Modifier.height(8.dp))
            }

            Button(
                onClick = { },
                shape = RectangleShape,
                modifier = Modifier.fillMaxWidth(),
            ) {
                Text("Rate Campsite")
            }

            Spacer(modifier = Modifier.height(8.dp))

            if (alreadyJoined && activeJoined != null && !activeJoined.isDrawn) {
                Button(
                    onClick = { leaveWaitlist() },
                    enabled = !isJoining,
                    shape = RectangleShape,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("leaveWaitlistButton"),
                ) {
                    Text(if (isJoining) "Leaving..." else "Leave Lottery/Waitlist")
                }
            } else {
                Button(
                    onClick = { joinWaitlist() },
                    enabled = !isJoining && campsite != null,
                    shape = RectangleShape,
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("joinWaitlistButton"),
                ) {
                    Text(if (isJoining) "Joining..." else "Join Lottery/Waitlist")
                }
            }
        }
    }
}

